render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); p <- ggplot2::ggplot(data, ggplot2::aes_string(x = cfg$x, y = cfg$y)) + ggplot2::geom_point(colour = cfg$color %||% "#0A84FF", alpha = 0.45) + ggplot2::stat_density_2d(ggplot2::aes(fill = ggplot2::after_stat(level)), geom = "polygon", alpha = 0.25, contour = TRUE) + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = cfg$x, y = cfg$y, fill = "密度"); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
